script:
frappe.ui.form.on('BOM', {
    after_load: function (frm) {
        if (frm.doc.custom_item_group && frm.doc.custom_item_group.toLowerCase() === 'chemical mix') {
            frm.clear_table('items');
            frm.set_df_property('custom_farm', 'reqd', 0);
            toggle_fields_visibility(frm);
        } else {
            reset_bom_fields(frm);
        }
    },

    // Event triggered when the main 'item' field is changed.
    item: function (frm) {
        if (frm.doc.item) {
            frappe.db.get_value('Item', frm.doc.item, 'item_group', (r) => {
                if (r.item_group) {
                    frm.set_value('custom_item_group', r.item_group);

                    if (frm.doc.custom_item_group && frm.doc.custom_item_group.toLowerCase() === 'chemical mix') {
                        frm.clear_table('items');
                        frm.set_df_property('custom_farm', 'reqd', 0);
                        toggle_fields_visibility(frm);
                        frm.doc.items.forEach(row => {
                            calculate_qty(frm, row.doctype, row.name);
                        });
                    } else {
                        reset_bom_fields(frm);
                    }
                }
            });
        }
    },

    refresh: function (frm) {
        if (frm.doc.custom_item_group && frm.doc.custom_item_group.toLowerCase() === 'chemical mix') {
            frm.set_df_property('custom_farm', 'reqd', 0);
            toggle_fields_visibility(frm);
            frm.doc.items.forEach(row => {
                calculate_qty(frm, row.doctype, row.name);
            });
        } else {
            reset_bom_fields(frm);
        }
    }
});
frappe.ui.form.on('BOM Item', {
    custom_application_rateper_ha_: function(frm, cdt, cdn) {
        if (frm.doc.custom_item_group && frm.doc.custom_item_group.toLowerCase() === 'chemical mix') {
            calculate_qty(frm, cdt, cdn);
        }
    }
});

function calculate_qty(frm, cdt, cdn) {
    const row = frappe.get_doc(cdt, cdn);
    const rate = row.custom_application_rateper_ha_ || 0;
    frappe.model.set_value(cdt, cdn, 'qty', 1 * rate);
}

function toggle_fields_visibility(frm) {
    const child_table_name = 'items';
    const all_managed_fields = [
        'is_stock_item',
        'allow_alternative_item',
        'source_warehouse',
        'custom_application_rateper_ha_'
    ];
    const child_grid = frm.fields_dict[child_table_name]?.grid;

    if (child_grid) {
        all_managed_fields.forEach(field => {
            child_grid.set_column_disp(field, false);
        });

        const fields_to_show_for_chemical_mix = [
            'custom_application_rateper_ha_'
        ];
        fields_to_show_for_chemical_mix.forEach(field => {
            child_grid.set_column_disp(field, true);
        });
    }

    const parent_fields_to_show = [
        'custom_water_ph',
        'custom_water_hardness',
    ];

    parent_fields_to_show.forEach(field => frm.toggle_display(field, true));
}

function reset_bom_fields(frm) {
    const child_table_name = 'items';
    const child_grid = frm.fields_dict[child_table_name]?.grid;

    const standard_fields = [
        'is_stock_item',
        'allow_alternative_item',
        'source_warehouse'
    ];

    const custom_fields = [
        'custom_application_rateper_ha_'
    ];

    const parent_fields_to_show = [
        'custom_mixing_instructions',
        'custom_target_pests'
    ];

    parent_fields_to_show.forEach(field => frm.toggle_display(field, false));

    if (child_grid) {
        standard_fields.forEach(field => {
            child_grid.set_column_disp(field, true);
        });
        custom_fields.forEach(field => {
            child_grid.set_column_disp(field, false);
        });
    }

    frm.set_value('allow_alternative_item', 0);
}

frappe.ui.form.on('Bed And Zone Automation', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 0 && !frm.is_new()) {
            frm.add_custom_button(__('Run Automation'), function() {
                frappe.confirm(
                    __('This will create new Bed and Zone documents. Do you want to continue?'),
                    () => {
                        frappe.call({
                            method: "createBedsAndZones",
                            args: {
                                doc_name: frm.doc.name
                            },
                            freeze: true,
                            freeze_message: "Automating zone and bed creation...",
                            callback: function(r) {
                                if (r.message) {
                                    frappe.msgprint(r.message);
                                }
                                frm.reload_doc();
                            },
                            error: function(r) {
                                if (r.message) {
                                    frappe.msgprint(r.message);
                                }
                            }
                        });
                    }
                );
            });
        }
    }
});

frappe.ui.form.on('Warehouse', {
    refresh(frm) {
        console.debug('[Warehouse Script] Starting refresh function at', new Date().toISOString());
        // Use a slight delay to ensure the map is fully loaded
        setTimeout(() => {
            console.debug('[Warehouse Script] Inside setTimeout');
            const mapControl = frm.fields_dict['custom_location'];
            if (!mapControl || !mapControl.map) {
                console.warn('[Warehouse Script] Map control or map instance not found');
                return;
            }
            const map = mapControl.map;
            console.debug('[Warehouse Script] Map instance retrieved:', map);

            // Clear existing layers from the map to avoid duplicates
            console.debug('[Warehouse Script] Clearing existing layers');
            map.eachLayer(layer => {
                if (!layer._url) { // Keep base layers, remove other layers
                    map.removeLayer(layer);
                }
            });
            console.debug('[Warehouse Script] Layers cleared');

            // Define base layers
            console.debug('[Warehouse Script] Setting up base layers');
            const satellite = L.tileLayer(
                'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
                    attribution: '© Esri',
                    maxZoom: 19
                }
            );

            const osm = L.tileLayer(
                'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    attribution: '© OpenStreetMap contributors',
                    maxZoom: 19
                }
            );

            // Add base layers and a control to switch between them
            console.debug('[Warehouse Script] Adding base layers to map');
            satellite.addTo(map);
            const baseLayers = { "Satellite View": satellite, "Street Map": osm };
            L.control.layers(baseLayers, null, { position: 'topright' }).addTo(map);
            console.debug('[Warehouse Script] Base layers and control added');

            // --- Custom GeoJSON Logic ---
            const rawGeoJSON = frm.doc.custom_raw_geojson;
            console.debug('[Warehouse Script] Raw custom_raw_geojson:', rawGeoJSON);
            if (rawGeoJSON) {
                try {
                    // Sanitize and parse the GeoJSON string
                    console.debug('[Warehouse Script] Sanitizing GeoJSON');
                    let cleanedGeoJSON = rawGeoJSON.trim();
                    if (cleanedGeoJSON.startsWith('"') && cleanedGeoJSON.endsWith('"')) {
                        cleanedGeoJSON = cleanedGeoJSON.slice(1, -1).replace(/\\"/g, '"');
                    }
                    console.debug('[Warehouse Script] Cleaned GeoJSON:', cleanedGeoJSON);

                    console.debug('[Warehouse Script] Parsing GeoJSON');
                    const geojson = JSON.parse(cleanedGeoJSON);
                    console.debug('[Warehouse Script] Parsed GeoJSON:', geojson);

                    if (geojson.type === 'FeatureCollection' && geojson.features && geojson.features.length > 0) {
                        console.debug('[Warehouse Script] Valid FeatureCollection detected, features:', geojson.features.length);
                        // Create a feature group to hold all polygons
                        const featureGroup = L.featureGroup();
                        console.debug('[Warehouse Script] Feature group created');

                        // Process each feature in the FeatureCollection
                        geojson.features.forEach((feature, index) => {
                            console.debug(`[Warehouse Script] Processing feature ${index}:`, feature);
                            if (feature.geometry && feature.geometry.type === 'Polygon') {
                                // Draw the polygon on the map
                                console.debug(`[Warehouse Script] Adding polygon for feature ${index}`);
                                const geoJsonLayer = L.geoJSON(feature, {
                                    style: {
                                        color: "#2b7fd4",
                                        weight: 3,
                                        opacity: 0.8,
                                        fillOpacity: 0.2
                                    },
                                    onEachFeature: (feature, layer) => {
                                        if (feature.properties && feature.properties.id) {
                                            console.debug(`[Warehouse Script] Binding popup for feature ${index}:`, feature.properties.id);
                                            layer.bindPopup(feature.properties.id);
                                        }
                                    }
                                }).addTo(map);
                                console.debug(`[Warehouse Script] Polygon added for feature ${index}`);

                                // Add the layer to the feature group
                                featureGroup.addLayer(geoJsonLayer);
                                console.debug(`[Warehouse Script] Feature ${index} added to feature group`);
                            } else {
                                console.warn(`[Warehouse Script] Feature ${index} is not a Polygon:`, feature);
                                frappe.msgprint(__('Invalid GeoJSON: One or more features are not Polygons.'));
                            }
                        });

                        // Fit the map view to the bounds of all polygons
                        console.debug('[Warehouse Script] Checking feature group bounds');
                        if (featureGroup.getBounds().isValid()) {
                            map.fitBounds(featureGroup.getBounds(), { padding: [50, 50] });
                            console.debug('[Warehouse Script] Map view set to bounds');
                        } else {
                            console.warn('[Warehouse Script] Invalid bounds for feature group');
                        }

                        // Calculate the centroid of all polygons
                        console.debug('[Warehouse Script] Calculating centroid');
                        let allCoordinates = [];
                        geojson.features.forEach(feature => {
                            if (feature.geometry && feature.geometry.type === 'Polygon') {
                                console.debug('[Warehouse Script] Collecting coordinates from feature:', feature.geometry.coordinates[0]);
                                allCoordinates.push(...feature.geometry.coordinates[0]);
                            }
                        });
                        console.debug('[Warehouse Script] All coordinates:', allCoordinates);

                        if (allCoordinates.length > 0) {
                            let sumLat = 0;
                            let sumLon = 0;
                            allCoordinates.forEach((coord, idx) => {
                                console.debug(`[Warehouse Script] Processing coordinate ${idx}:`, coord);
                                sumLon += coord[0];
                                sumLat += coord[1];
                            });

                            const avgLon = sumLon / allCoordinates.length;
                            const avgLat = sumLat / allCoordinates.length;
                            console.debug('[Warehouse Script] Calculated centroid:', { avgLat, avgLon });

                            // Set custom_location to GeoJSON Feature with point_type
                            const locationGeoJSON = {
                                type: "Feature",
                                geometry: {
                                    type: "Point",
                                    coordinates: [avgLon, avgLat]
                                },
                                properties: {
                                    point_type: "point"
                                }
                            };
                            let locationString = JSON.stringify(locationGeoJSON);
                            console.debug('[Warehouse Script] Setting custom_location to GeoJSON Feature:', locationString);

                            // Sanitize to prevent double-stringification
                            if (locationString.startsWith('"') && locationString.endsWith('"')) {
                                locationString = locationString.slice(1, -1);
                            }
                            console.debug('[Warehouse Script] Final custom_location value:', locationString);

                            // Set the value of the Geolocation field
                            frm.set_value('custom_location', locationString);
                            console.debug('[Warehouse Script] custom_location set');

                            // Log plain string format for reference
                            console.debug('[Warehouse Script] Plain string format (for reference):', `${avgLat},${avgLon}`);

                        } else {
                            console.warn('[Warehouse Script] No valid coordinates found for centroid');
                            frappe.msgprint(__('No valid coordinates found to calculate centroid.'));
                        }

                    } else {
                        console.warn('[Warehouse Script] Invalid GeoJSON structure:', geojson);
                        frappe.msgprint(__('Invalid GeoJSON: Must be a FeatureCollection with Polygon features.'));
                    }

                } catch (e) {
                    console.error('[Warehouse Script] Error processing GeoJSON:', e, 'Raw input:', rawGeoJSON);
                    frappe.msgprint(__('Invalid JSON format in `custom_raw_geojson`. Check the console for details.'));
                }
            } else {
                console.warn('[Warehouse Script] No GeoJSON data found in custom_raw_geojson');
            }
            console.debug('[Warehouse Script] Refresh function completed');
        }, 300);
    },

    // Trigger the refresh logic when the field's value changes
    custom_raw_geojson: function(frm) {
        console.debug('[Warehouse Script] custom_raw_geojson changed, triggering refresh');
        frm.refresh();
    }
});

frappe.ui.form.on('Pest', {
    refresh: function(frm) {
        // Set the initial value of pests_legend_color if the form is new
        if (frm.is_new()) {
            frm.set_value('pests_legend_color', '');
        }
    },
    severity: function(frm) {
        // Find the 'Moderate' severity row
        const moderateRow = frm.doc.severity.find(row => row.severity === 'Moderate');

        // If a moderate row exists, update the pests_legend_color
        if (moderateRow) {
            frm.set_value('pests_legend_color', moderateRow.color);
        }
    }
});

frappe.ui.form.on('Scouting Severity Scale', {
    color: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.severity === 'Moderate') {
            frm.set_value('pests_legend_color', row.color);
        }
    }
});

frappe.ui.form.on('Item', {
    refresh(frm) {
        toggle_custom_fields(frm);
        toggle_type_fields(frm, false);
    },
    item_group(frm) {
        toggle_custom_fields(frm, false); // true means clear old values
    },
    custom_type(frm) {
        toggle_type_fields(frm, false); // clear old values
    },
    custom_irac(frm) {
        fetch_irac_moa(frm);
    },
    custom_frac(frm) {
        fetch_frac_moa(frm);
    },
    custom_ghs(frm) {
        fetch_ghs_description(frm);
    }
});

function toggle_custom_fields(frm, clear_values = false) {
    let group_field_map = {
        "Spray Roses": ["custom_chemical_intervention_threshhold"],
        "Standard Roses": ["custom_chemical_intervention_threshhold"],
        "Summer Flowers": ["custom_chemical_intervention_threshhold"],
        "CHEMICALS": [
            "custom_type",
            "custom_ghs",
            "custom_ghs_description",
            "custom_toxicity",
            "custom_irac",
            "custom_irac_moa",
            "custom_frac",
            "custom_frac_moa",
            "custom_reentry_interval_hrs",
            "custom_active_ingredients",
            "custom_targets"
        ],
        "AVOCADO CHEMICALS": [
            "custom_type",
            "custom_ghs",
            "custom_ghs_description",
            "custom_toxicity",
            "custom_irac",
            "custom_irac_moa",
            "custom_frac",
            "custom_frac_moa",
            "custom_reentry_interval_hrs",
            "custom_active_ingredients",
            "custom_targets"
        ],
    };

    // Flatten all possible fields
    let all_fields = Object.values(group_field_map).flat();

    // If item_group not selected, hide and optionally clear all fields
    if (!frm.doc.item_group) {
        all_fields.forEach(field => {
            frm.set_df_property(field, "hidden", 1);
            if (clear_values) frm.set_value(field, null);
        });
        return;
    }

    // Determine which fields should be shown
    let fields_to_show = group_field_map[frm.doc.item_group] || [];

    // Hide (and optionally clear) irrelevant fields
    all_fields.forEach(field => {
        if (!fields_to_show.includes(field)) {
            frm.set_df_property(field, "hidden", 1);
            if (clear_values) frm.set_value(field, null);
        }
    });

    // Show relevant fields
    fields_to_show.forEach(field => {
        frm.set_df_property(field, "hidden", 0);
    });
}

function toggle_type_fields(frm, clear_values = false) {
    let type_field_map = {
        "Insecticide": [
            "custom_irac",
            "custom_irac_moa",
            "custom_reentry_interval_hrs",
            "custom_active_ingredients",
            "custom_targets"
        ],
        "Fungicide": [
            "custom_frac",
            "custom_frac_moa",
            "custom_reentry_interval_hrs",
            "custom_active_ingredients",
            "custom_targets"
        ],
        "Adjuvant": [],
        "pH Buffer": [],
    };

    const grid = frm.fields_dict["custom_targets"].grid;
    const type = frm.doc.custom_type;

    grid.toggle_display("disease", type === "Fungicide");
    grid.toggle_display("pest", type === "Insecticide");

    grid.refresh();

    let all_type_fields = Object.values(type_field_map).flat();
    if (!frm.doc.custom_type) {
        all_type_fields.forEach(field => {
            frm.set_df_property(field, "hidden", 1);
            if (clear_values) frm.set_value(field, null);
        });
        return;
    }

    let fields_to_show = type_field_map[frm.doc.custom_type] || [];

    all_type_fields.forEach(field => {
        if (!fields_to_show.includes(field)) {
            frm.set_df_property(field, "hidden", 1);
            if (clear_values) frm.set_value(field, null);
        }
    });

    fields_to_show.forEach(field => {
        frm.set_df_property(field, "hidden", 0);
    });
}

function fetch_irac_moa(frm) {
    if (!frm.doc.custom_irac || frm.doc.custom_irac.length === 0) {
        frm.set_value("custom_irac_moa", null);
        return;
    }

    // Collect all IRAC codes from the child table
    let irac_codes = frm.doc.custom_irac.map(row => row.code).filter(x => x);

    if (irac_codes.length === 0) {
        frm.set_value("custom_irac_moa", null);
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "IRAC Code",
            filters: { name: ["in", irac_codes] },
            fields: ["primary_site_of_action"]
        },
        callback: function (r) {
            if (r.message) {
                let moa_list = r.message.map(d => d.primary_site_of_action);
                frm.set_value("custom_irac_moa", moa_list.join(", "));
            }
        }
    });
}

function fetch_frac_moa(frm) {
    if (!frm.doc.custom_frac || frm.doc.custom_frac.length === 0) {
        frm.set_value("custom_frac_moa", null);
        return;
    }

    // Collect all IRAC codes from the child table
    let frac_codes = frm.doc.custom_frac.map(row => row.code).filter(x => x);

    if (frac_codes.length === 0) {
        frm.set_value("custom_frac_moa", null);
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "FRAC Code",
            filters: { name: ["in", frac_codes] },
            fields: ["mode_of_action"]
        },
        callback: function (r) {
            if (r.message) {
                let moa_list = r.message.map(d => d.mode_of_action);
                frm.set_value("custom_frac_moa", moa_list.join(", "));
            }
        }
    });
}

function fetch_ghs_description(frm) {
    if (!frm.doc.custom_ghs || frm.doc.custom_ghs.length === 0) {
        frm.set_value("custom_ghs_description", null);
        return;
    }

    // Collect all IRAC codes from the child table
    let custom_ghs = frm.doc.custom_ghs.map(row => row.code).filter(x => x);

    if (custom_ghs.length === 0) {
        frm.set_value("custom_ghs_description", null);
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "GHS Code",
            filters: { name: ["in", custom_ghs] },
            fields: ["description"]
        },
        callback: function (r) {
            if (r.message) {
                let moa_list = r.message.map(d => d.description);
                frm.set_value("custom_ghs_description", moa_list.join(", "));
            }
        }
    });
}

frappe.ui.form.on('Work Order', {
    after_load: function (frm) {
        if (frm.doc.custom_type && frm.doc.custom_type.toLowerCase() === 'application floor plan') {
            toggle_fields_visibility(frm);
        } else {
            reset_bom_fields(frm);
        }
    },

    refresh: function (frm) {
        if (frm.doc.custom_type && frm.doc.custom_type.toLowerCase() === 'application floor plan') {
            toggle_fields_visibility(frm);
        } else {
            reset_bom_fields(frm);
        }
    }
});

function toggle_fields_visibility(frm) {
    const parent_fields_to_show = [
        'custom_validation_status',
        'custom_greenhouse',
        'custom_scope',
        'custom_scope_details', 
        'custom_area',
        'custom_water_volume',
        'custom_water_ph',
        'custom_water_hardness',
        'custom_variety',
        'custom_spray_type',
        'custom_kit',
        'custom_targets',
        'custom_reentry_period_hrs',
        'custom_scheduled_application_time',
        'custom_reentry_time',
        'custom_spray_team'
    ];

    parent_fields_to_show.forEach(field => frm.toggle_display(field, true));
}

function reset_bom_fields(frm) {
    const parent_fields_to_show = [
        'custom_validation_status',
        'custom_greenhouse',
        'custom_scope',
        'custom_scope_details', 
        'custom_area',
        'custom_water_volume',
        'custom_water_ph',
        'custom_water_hardness',
        'custom_variety',
        'custom_spray_type',
        'custom_kit',
        'custom_targets',
        'custom_reentry_period_hrs',
        'custom_scheduled_application_time',
        'custom_reentry_time',
        'custom_spray_team'
    ];
    parent_fields_to_show.forEach(field => frm.toggle_display(field, false));
}

frappe.ui.form.on('Work Order', {
    refresh: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        setTimeout(function() {
            calculate_reentry_period(frm);
        }, 100);
    },
    onload: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    },
    after_load: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    },
    custom_scheduled_application_time: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_time(frm);
    },
    custom_reentry_period_hrs: function(frm) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_time(frm);
    }
});

frappe.ui.form.on('Work Order Item', {
    required_items_add: function(frm, cdt, cdn) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    },
    required_items_remove: function(frm, cdt, cdn) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    },
    item_code: function(frm, cdt, cdn) {
        if (frm.doc.custom_type !== 'Application Floor Plan') {
            return;
        }
        calculate_reentry_period(frm);
    }
});

function calculate_reentry_time(frm) {
    let scheduled_time = frm.doc.custom_scheduled_application_time;
    let reentry_hours = frm.doc.custom_reentry_period_hrs || 0;

    if (!scheduled_time) {
        frm.set_value('custom_reentry_time', null);
        return;
    }

    reentry_hours = parseFloat(reentry_hours);

    if (isNaN(reentry_hours) || reentry_hours < 0) {
        frappe.msgprint({
            title: __('Error'),
            indicator: 'red',
            message: __('Invalid reentry period. Please check the items and try again.')
        });
        frm.set_value('custom_reentry_time', null);
        return;
    }

    try {
        let scheduled_date = new Date(scheduled_time);

        if (isNaN(scheduled_date.getTime())) {
            throw new Error('Invalid scheduled application time format');
        }

        let current_utc_hours = scheduled_date.getUTCHours();
        scheduled_date.setUTCHours(current_utc_hours + reentry_hours);

        if (isNaN(scheduled_date.getTime())) {
            throw new Error('Invalid reentry time calculation result');
        }

        // Manual formatting to YYYY-MM-DD HH:MM:SS
        let YYYY = scheduled_date.getFullYear();
        let MM = String(scheduled_date.getMonth() + 1).padStart(2, '0');
        let DD = String(scheduled_date.getDate()).padStart(2, '0');
        let HH = String(scheduled_date.getHours()).padStart(2, '0');
        let mm = String(scheduled_date.getMinutes()).padStart(2, '0');
        let SS = String(scheduled_date.getSeconds()).padStart(2, '0');

        let reentry_time = `${YYYY}-${MM}-${DD} ${HH}:${mm}:${SS}`;

        frm.set_value('custom_reentry_time', reentry_time);

    } catch (error) {
        frappe.msgprint({
            title: __('Calculation Error'),
            indicator: 'red',
            message: __('Failed to calculate reentry time: {0}', [error.message])
        });
        frm.set_value('custom_reentry_time', null);
    }
}

function calculate_reentry_period(frm) {
    if (!frm.doc.required_items || frm.doc.required_items.length === 0) {
        frm.set_value('custom_reentry_period_hrs', 0);
        return;
    }

    let item_codes = [];
    frm.doc.required_items.forEach(function(item) {
        if (item.item_code) {
            item_codes.push(item.item_code);
        }
    });

    if (item_codes.length === 0) {
        frm.set_value('custom_reentry_period_hrs', 0);
        return;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Item',
            filters: {
                'name': ['in', item_codes]
            },
            fields: ['name', 'custom_reentry_interval_hrs']
        },
        callback: function(r) {
            if (r.message) {
                let max_reentry = 0;
                r.message.forEach(function(item) {
                    let reentry_hrs = item.custom_reentry_interval_hrs || 0;
                    reentry_hrs = parseFloat(reentry_hrs);
                    if (reentry_hrs > max_reentry) {
                        max_reentry = reentry_hrs;
                    }
                });
                frm.set_value('custom_reentry_period_hrs', max_reentry);
            }
        }
    });
}

frappe.ui.form.on("Work Order", {

    refresh(frm) {
        if (frm.doc.custom_type !== "Application Floor Plan") return;

        const removeButtons = () => {
            frm.remove_custom_button("Start");
            frm.remove_custom_button("Finish");
            frm.remove_custom_button("Status");
        };

        removeButtons();
        setTimeout(removeButtons, 100);
        setTimeout(removeButtons, 500);
        setTimeout(removeButtons, 1000);
    }

});

// ============================================================
//  Work Order — List Client Script  v7
//
//  New in v6:
//  - Date picker inside farm picker modal (defaults to today)
//  - "Show All Dates" clears the date filter
//  - Farm cards show: total WOs for the date, how many still
//    need approval (no draft SE yet) vs already forwarded
//  - Pulsing amber dot = has unapproved WOs needing action
//  - Solid green dot  = all WOs for that farm already forwarded
//  - Bulk Cancel (Stop) button in approval modal alongside
//    Approve Selected — calls stop_unstop API in sequence
//  - Red progress bar for stop flow, green for approve flow
// ============================================================

const AFP_TYPE    = "Application Floor Plan";
const GM_ROLE     = "General Manager";
const STORES_ROLE = "Stock User";

let _scoutingCache = {};
let _qrLibReady = false;

const _loadQrLib = () => new Promise((resolve, reject) => {
    if (_qrLibReady) return resolve();
    if (document.getElementById("qrcode-js")) { _qrLibReady = true; return resolve(); }
    const script   = document.createElement("script");
    script.id      = "qrcode-js";
    script.src     = "https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js";
    script.onload  = () => { _qrLibReady = true; resolve(); };
    script.onerror = () => reject(new Error("Failed to load QR library"));
    document.head.appendChild(script);
});

function fmtDateISO(d) {
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    return d.getFullYear() + "-" + mm + "-" + dd;
}
function todayISO() { return fmtDateISO(new Date()); }

// ════════════════════════════════════════════════════════════
//  List-view entry point
// ════════════════════════════════════════════════════════════

frappe.listview_settings["Work Order"] = {
    async onload(listview) {
        injectStyles();
        injectHeatmapStyles();

        const isGM     = frappe.user.has_role(GM_ROLE);
        const isStores = frappe.user.has_role(STORES_ROLE);

        if (isGM) {
            listview.page.add_button("Approve Spray Plans", () => openFarmPicker());
        }

        if (!isStores) {
            hidePickListButton();
        }
    }
};

function hidePickListButton() {
    let attempts = 20;
    const interval = setInterval(() => {
        const allBtns = [...document.querySelectorAll(".page-actions .btn, .page-actions .dropdown-item, .actions-btn-group .dropdown-item")];
        const pickBtn = allBtns.find(b => (b.textContent || "").trim() === "Create Pick List");
        if (pickBtn) {
            pickBtn.style.display = "none";
            const li = pickBtn.closest("li");
            if (li) li.style.display = "none";
            clearInterval(interval);
            return;
        }
        if (--attempts <= 0) clearInterval(interval);
    }, 100);
}

// ════════════════════════════════════════════════════════════
//  STEP 1 — Farm Picker (date picker + pending indicators)
// ════════════════════════════════════════════════════════════

function openFarmPicker(initialFrom, initialTo) {
    const overlay = buildOverlay();
    const modal   = buildModal();
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    modal.appendChild(buildHeader("Approve Spray Plans — Select Farm", () => overlay.remove()));

    const body = document.createElement("div");
    body.className = "sp-body";
    modal.appendChild(body);

    // Date picker bar
    const dateBar = document.createElement("div");
    dateBar.style.cssText = "display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:20px;" +
        "padding:14px 16px;background:#f8fafc;border:1.5px solid #e5e7eb;border-radius:10px;";

    const fromLbl = document.createElement("label");
    fromLbl.style.cssText = "font-size:.8rem;font-weight:700;color:#374151;white-space:nowrap;";
    fromLbl.textContent = "From:";

    const fromInput = document.createElement("input");
    fromInput.type  = "date";
    fromInput.value = initialFrom || todayISO();
    fromInput.style.cssText = "padding:7px 12px;border:1.5px solid #d1d5db;border-radius:8px;" +
        "font-size:.85rem;color:#111827;background:#fff;cursor:pointer;outline:none;min-width:140px;";

    const toLbl = document.createElement("label");
    toLbl.style.cssText = "font-size:.8rem;font-weight:700;color:#374151;white-space:nowrap;";
    toLbl.textContent = "To:";

    const toInput = document.createElement("input");
    toInput.type  = "date";
    toInput.value = initialTo || todayISO();
    toInput.style.cssText = "padding:7px 12px;border:1.5px solid #d1d5db;border-radius:8px;" +
        "font-size:.85rem;color:#111827;background:#fff;cursor:pointer;outline:none;min-width:140px;";

    const clearBtn = document.createElement("button");
    clearBtn.className = "sp-btn sp-btn-cancel";
    clearBtn.textContent = "Show All Dates";
    clearBtn.style.cssText = "font-size:.75rem;padding:7px 14px;white-space:nowrap;";

    const loadBtn = document.createElement("button");
    loadBtn.className = "sp-btn sp-btn-approve";
    loadBtn.textContent = "Load";
    loadBtn.style.cssText = "font-size:.75rem;padding:7px 20px;";

    dateBar.appendChild(fromLbl);
    dateBar.appendChild(fromInput);
    dateBar.appendChild(toLbl);
    dateBar.appendChild(toInput);
    dateBar.appendChild(clearBtn);
    dateBar.appendChild(loadBtn);
    body.appendChild(dateBar);

    const statusLine = document.createElement("p");
    statusLine.style.cssText = "font-size:.75rem;color:#6b7280;margin-bottom:12px;min-height:18px;";
    body.appendChild(statusLine);

    const farmGrid = document.createElement("div");
    farmGrid.className = "sp-farm-grid";
    body.appendChild(farmGrid);

    function loadFarms(fromDate, toDate) {
        farmGrid.innerHTML = "<div style='grid-column:1/-1;text-align:center;padding:32px;color:#6b7280;font-size:.85rem;'>Loading...</div>";
        statusLine.textContent = "";

        const filters = [
            ["custom_type", "=", AFP_TYPE],
            ["status",      "=", "Not Started"],
            ["docstatus",   "=", 1]
        ];

        if (fromDate) {
            filters.push(["custom_scheduled_application_time", ">=", fromDate + " 00:00:00"]);
        }
        if (toDate) {
            const nextDay = new Date(toDate);
            nextDay.setDate(nextDay.getDate() + 1);
            filters.push(["custom_scheduled_application_time", "<",  fmtDateISO(nextDay) + " 00:00:00"]);
        }

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype:  "Work Order",
                filters:  filters,
                fields:   ["name", "custom_greenhouse", "creation", "custom_scheduled_application_time"],
                limit:    0,
                order_by: "creation desc"
            }
        }).then(r => {
            const woList = r.message || [];
            farmGrid.innerHTML = "";

            if (!woList.length) {
                statusLine.textContent = (fromDate || toDate)
                    ? "No unstarted spray plans found for selected range."
                    : "No unstarted spray plans found.";
                farmGrid.innerHTML = "<div style='grid-column:1/-1;text-align:center;padding:32px;color:#6b7280;font-size:.85rem;'>" +
                    ((fromDate || toDate) ? "No plans scheduled for this date range." : "No pending plans found.") + "</div>";
                return;
            }

            statusLine.textContent = woList.length + " work order" + (woList.length !== 1 ? "s" : "") +
                " found" + (fromDate ? " from " + fromDate : "") + (toDate && toDate !== fromDate ? " to " + toDate : "") + ". Checking approval status...";

            const farmMap = {};
            woList.forEach(wo => {
                const farm = deriveFarm(wo.custom_greenhouse);
                if (!farm) return;
                if (!farmMap[farm]) farmMap[farm] = { names: [], latest: wo.creation };
                farmMap[farm].names.push(wo.name);
                if (wo.creation > farmMap[farm].latest) farmMap[farm].latest = wo.creation;
            });

            const allNames = woList.map(wo => wo.name);

            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Stock Entry",
                    filters: [
                        ["work_order", "in", allNames],
                        ["purpose",    "=", "Material Transfer for Manufacture"],
                        ["docstatus",  "=", 0]
                    ],
                    fields: ["work_order"],
                    limit:  0
                }
            }).then(seResp => {
                const forwardedSet = new Set();
                (seResp.message || []).forEach(se => forwardedSet.add(se.work_order));

                const farms = Object.keys(farmMap).sort((a, b) => farmMap[b].latest.localeCompare(farmMap[a].latest));

                statusLine.textContent = woList.length + " work order" + (woList.length !== 1 ? "s" : "") +
                    " found" + (fromDate ? " from " + fromDate : "") + (toDate && toDate !== fromDate ? " to " + toDate : "") + ".";

                farms.forEach(farm => {
                    const names      = farmMap[farm].names;
                    const latest     = farmMap[farm].latest;
                    const forwarded  = names.filter(n => forwardedSet.has(n)).length;
                    const unapproved = names.length - forwarded;
                    const latestDate = new Date(latest).toLocaleDateString("en-GB", {
                        day: "numeric", month: "short", year: "numeric"
                    });

                    const btn = document.createElement("button");
                    btn.className = "sp-farm-btn";
                    if (unapproved === 0) {
                        btn.style.borderColor = "#059669";
                        btn.style.background  = "#f0fdf4";
                    }

                    const topRow = document.createElement("div");
                    topRow.style.cssText = "display:flex;align-items:center;justify-content:space-between;gap:6px;width:100%;margin-bottom:8px;";
                    const farmName = document.createElement("span");
                    farmName.style.cssText = "font-weight:700;font-size:.95rem;color:#111827;";
                    farmName.textContent = farm;
                    const badge = document.createElement("span");
                    badge.className = "sp-farm-badge";
                    badge.style.background = unapproved > 0 ? "#dc2626" : "#059669";
                    badge.textContent = names.length;
                    topRow.appendChild(farmName);
                    topRow.appendChild(badge);

                    const midRow = document.createElement("div");
                    midRow.style.cssText = "display:flex;align-items:center;gap:6px;margin-bottom:4px;";
                    const dot = document.createElement("span");
                    dot.className = unapproved > 0 ? "sp-farm-pending-dot" : "sp-farm-approved-dot";
                    const statusTxt = document.createElement("span");
                    statusTxt.style.cssText = "font-size:.75rem;font-weight:600;color:" + (unapproved > 0 ? "#d97706" : "#059669") + ";";
                    statusTxt.textContent = unapproved > 0
                        ? unapproved + " pending approval" + (unapproved !== 1 ? "s" : "")
                        : "All forwarded to Stores";
                    midRow.appendChild(dot);
                    midRow.appendChild(statusTxt);

                    const subRow = document.createElement("div");
                    subRow.style.cssText = "font-size:.68rem;color:#9ca3af;margin-bottom:4px;";
                    if (forwarded > 0) {
                        subRow.textContent = forwarded + " already forwarded";
                    }

                    const dateRow = document.createElement("div");
                    dateRow.style.cssText = "font-size:.68rem;color:#9ca3af;";
                    dateRow.textContent = "Latest: " + latestDate;

                    btn.appendChild(topRow);
                    btn.appendChild(midRow);
                    if (forwarded > 0) btn.appendChild(subRow);
                    btn.appendChild(dateRow);

                    btn.addEventListener("click", () => {
                        overlay.remove();
                        openApprovalModal(farm, names, () => openFarmPicker(fromInput.value, toInput.value));
                    });
                    farmGrid.appendChild(btn);
                });
            }).catch(() => {
                const farms = Object.keys(farmMap).sort((a, b) => farmMap[b].latest.localeCompare(farmMap[a].latest));
                statusLine.textContent = woList.length + " work orders found.";
                farms.forEach(farm => {
                    const names  = farmMap[farm].names;
                    const latest = farmMap[farm].latest;
                    const latestDate = new Date(latest).toLocaleDateString("en-GB", { day:"numeric", month:"short", year:"numeric" });

                    const btn = document.createElement("button");
                    btn.className = "sp-farm-btn";

                    const topRow = document.createElement("div");
                    topRow.style.cssText = "display:flex;align-items:center;justify-content:space-between;gap:6px;width:100%;margin-bottom:8px;";
                    const farmName = document.createElement("span");
                    farmName.style.cssText = "font-weight:700;font-size:.95rem;color:#111827;";
                    farmName.textContent = farm;
                    const badge = document.createElement("span");
                    badge.className = "sp-farm-badge";
                    badge.textContent = names.length;
                    topRow.appendChild(farmName);
                    topRow.appendChild(badge);

                    const midRow = document.createElement("div");
                    midRow.style.cssText = "display:flex;align-items:center;gap:6px;margin-bottom:4px;";
                    const dot = document.createElement("span"); dot.className = "sp-farm-pending-dot";
                    const statusTxt = document.createElement("span");
                    statusTxt.style.cssText = "font-size:.75rem;font-weight:600;color:#d97706;";
                    statusTxt.textContent = names.length + " plan" + (names.length !== 1 ? "s" : "");
                    midRow.appendChild(dot); midRow.appendChild(statusTxt);

                    const dateRow = document.createElement("div");
                    dateRow.style.cssText = "font-size:.68rem;color:#9ca3af;";
                    dateRow.textContent = "Latest: " + latestDate;

                    btn.appendChild(topRow); btn.appendChild(midRow); btn.appendChild(dateRow);
                    btn.addEventListener("click", () => { overlay.remove(); openApprovalModal(farm, names, () => openFarmPicker(fromInput.value, toInput.value)); });
                    farmGrid.appendChild(btn);
                });
            });
        }).catch(e => {
            farmGrid.innerHTML = "";
            statusLine.textContent = "Failed to load: " + (e.message || e);
        });
    }

    loadBtn.addEventListener("click", () => loadFarms(fromInput.value || null, toInput.value || null));
    clearBtn.addEventListener("click", () => { fromInput.value = ""; toInput.value = ""; loadFarms(null, null); });
    fromInput.addEventListener("keydown", e => { if (e.key === "Enter") loadFarms(fromInput.value || null, toInput.value || null); });
    toInput.addEventListener("keydown", e => { if (e.key === "Enter") loadFarms(fromInput.value || null, toInput.value || null); });

    // Arrow-key scroll
    modal.setAttribute("tabindex", "-1");
    modal.style.outline = "none";
    modal.addEventListener("keydown", e => {
        if (e.key === "ArrowDown") { body.scrollTop += 100; e.preventDefault(); }
        if (e.key === "ArrowUp")   { body.scrollTop -= 100; e.preventDefault(); }
        if (e.key === "Escape")    { overlay.remove(); }
    });
    requestAnimationFrame(() => modal.focus());

    loadFarms(initialFrom || todayISO(), initialTo || todayISO());
}

// ════════════════════════════════════════════════════════════
//  STEP 2 — Approval Modal
// ════════════════════════════════════════════════════════════

function openApprovalModal(farm, woNames, backFn) {
    const overlay = buildOverlay();
    const modal   = buildModal();
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    modal.appendChild(buildHeader("Approve Spray Plans — " + farm, () => overlay.remove(), backFn));

    modal.setAttribute("tabindex", "-1");
    modal.style.outline = "none";
    modal.addEventListener("keydown", e => {
        const bodyEl = modal.querySelector(".sp-body");
        if (e.key === "ArrowDown" && bodyEl) { bodyEl.scrollTop += 100; e.preventDefault(); }
        if (e.key === "ArrowUp"   && bodyEl) { bodyEl.scrollTop -= 100; e.preventDefault(); }
        if (e.key === "Escape")              { overlay.remove(); }
    });
    requestAnimationFrame(() => modal.focus());

    const body = document.createElement("div");
    body.className = "sp-body";
    body.innerHTML = "<div style='text-align:center;padding:40px;color:#6b7280;'>Loading spray plan details...</div>";
    modal.appendChild(body);

    Promise.all(woNames.map(name => frappe.db.get_doc("Work Order", name)))
        .then(allWorkOrders => {
            allWorkOrders.sort((a, b) => (b.creation || "").localeCompare(a.creation || ""));

            return frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Stock Entry",
                    filters: [
                        ["work_order", "in", woNames],
                        ["purpose",    "=", "Material Transfer for Manufacture"],
                        ["docstatus",  "=", 0]
                    ],
                    fields: ["work_order"],
                    limit:  0
                }
            }).then(seResp => {
                const alreadyRaised = new Set();
                (seResp.message || []).forEach(se => alreadyRaised.add(se.work_order));
                return { allWorkOrders, alreadyRaised };
            }).catch(() => ({ allWorkOrders, alreadyRaised: new Set() }));
        })
        .then(result => {
            const allWorkOrders = result.allWorkOrders;
            const alreadyRaised = result.alreadyRaised;
            const workOrders    = allWorkOrders.filter(wo => !alreadyRaised.has(wo.name));
            const pendingWOs    = allWorkOrders.filter(wo => alreadyRaised.has(wo.name));

            body.innerHTML = "";

            if (pendingWOs.length) {
                const notice = document.createElement("div");
                notice.className = "sp-pending-notice";
                notice.innerHTML = "<span style='font-size:.8rem;font-weight:600;color:#92400e;'>Already forwarded to Stores:</span>" +
                    "<span style='font-size:.8rem;color:#92400e;'>" +
                    pendingWOs.length + " plan" + (pendingWOs.length !== 1 ? "s" : "") + " — " +
                    pendingWOs.map(wo => "<a href='/app/work-order/" + wo.name + "' target='_blank' style='color:#d97706;font-weight:600;'>" + wo.name + "</a>").join(", ") + "</span>";
                body.appendChild(notice);
            }

            if (!workOrders.length) {
                const emptyDiv = document.createElement("div");
                emptyDiv.style.cssText = "text-align:center;padding:32px;color:#6b7280;";
                emptyDiv.textContent = "All spray plans for this farm have already been forwarded to Stores.";
                body.appendChild(emptyDiv);
                const footer2  = document.createElement("div"); footer2.className = "sp-footer";
                const close2   = document.createElement("button"); close2.className = "sp-btn sp-btn-cancel"; close2.textContent = "Close";
                close2.addEventListener("click", () => overlay.remove());
                footer2.appendChild(close2);
                modal.appendChild(footer2);
                return;
            }

            const byGH = {};
            workOrders.forEach(wo => {
                const gh = wo.custom_greenhouse || "Unknown";
                if (!byGH[gh]) byGH[gh] = [];
                byGH[gh].push(wo);
            });

            const checkboxMap = {};

            Object.keys(byGH).sort().forEach(gh => {
                const wos = byGH[gh];

                const section  = document.createElement("div"); section.className = "sp-gh-section";
                const ghHeader = document.createElement("div"); ghHeader.className = "sp-gh-header";
                const ghCheck  = document.createElement("input"); ghCheck.type = "checkbox"; ghCheck.title = "Select / deselect all";
                const ghName   = document.createElement("span"); ghName.className = "sp-gh-name"; ghName.textContent = gh;
                const ghMeta   = document.createElement("span"); ghMeta.className = "sp-gh-meta";
                ghMeta.textContent = wos.length + " plan" + (wos.length !== 1 ? "s" : "");

                ghHeader.appendChild(ghCheck);
                ghHeader.appendChild(ghName);
                ghHeader.appendChild(ghMeta);
                section.appendChild(ghHeader);

                const ghCheckboxes = [];
                wos.forEach(wo => {
                    const cb = document.createElement("input"); cb.type = "checkbox"; cb.dataset.wo = wo.name;
                    checkboxMap[wo.name] = cb;
                    ghCheckboxes.push(cb);
                    cb.addEventListener("change", () => { syncGhCheckbox(ghCheck, ghCheckboxes); updateFooter(); });
                    section.appendChild(buildWoCard(wo, cb));
                });
                body.appendChild(section);

                ghCheck.addEventListener("change", () => {
                    ghCheckboxes.forEach(c => { c.checked = ghCheck.checked; });
                    ghCheck.indeterminate = false;
                    updateFooter();
                });
                ghHeader.addEventListener("click", e => {
                    if (e.target === ghCheck) return;
                    ghCheck.checked = !ghCheck.checked;
                    ghCheckboxes.forEach(c => { c.checked = ghCheck.checked; });
                    ghCheck.indeterminate = false;
                    updateFooter();
                });
            });

            const footer     = document.createElement("div"); footer.className = "sp-footer"; modal.appendChild(footer);
            const footerInfo = document.createElement("div"); footerInfo.className = "sp-footer-info"; footerInfo.id = "sp-footer-info";
            const btnWrap    = document.createElement("div"); btnWrap.style.cssText = "display:flex;gap:8px;flex-wrap:wrap;";

            const btnCancel = document.createElement("button");
            btnCancel.className = "sp-btn sp-btn-cancel";
            btnCancel.textContent = "Cancel";
            btnCancel.addEventListener("click", () => overlay.remove());

            const btnSelectAll = document.createElement("button");
            btnSelectAll.className = "sp-btn sp-btn-cancel";
            btnSelectAll.textContent = "Select All";
            btnSelectAll.addEventListener("click", () => {
                Object.values(checkboxMap).forEach(cb => { cb.checked = true; });
                body.querySelectorAll(".sp-gh-header input[type=checkbox]").forEach(c => { c.checked = true; c.indeterminate = false; });
                updateFooter();
            });

            const btnStop = document.createElement("button");
            btnStop.className = "sp-btn sp-btn-stop";
            btnStop.textContent = "Stop Selected";
            btnStop.disabled = true;
            btnStop.id = "sp-stop-btn";

            btnStop.addEventListener("click", () => {
                const selected = Object.keys(checkboxMap).filter(name => checkboxMap[name].checked);
                if (!selected.length) return;

                const existing = footer.querySelector(".sp-inline-confirm");
                if (existing) { existing.remove(); return; }

                const confirmBar = document.createElement("div");
                confirmBar.className = "sp-inline-confirm";
                confirmBar.style.cssText = "width:100%;padding:10px 14px;background:#fef2f2;border:1.5px solid #fecaca;" +
                    "border-radius:8px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;";

                const msg = document.createElement("span");
                msg.style.cssText = "font-size:.8rem;font-weight:600;color:#dc2626;flex:1;";
                msg.textContent = "Stop " + selected.length + " work order" + (selected.length !== 1 ? "s" : "") +
                    "? This will prevent material transfer and cannot be undone.";

                const btnConfirmWrap = document.createElement("div");
                btnConfirmWrap.style.cssText = "display:flex;gap:8px;flex-shrink:0;";

                const btnDismiss = document.createElement("button");
                btnDismiss.className = "sp-btn sp-btn-cancel";
                btnDismiss.style.cssText = "font-size:.75rem;padding:6px 14px;";
                btnDismiss.textContent = "Cancel";
                btnDismiss.addEventListener("click", () => confirmBar.remove());

                const btnConfirm = document.createElement("button");
                btnConfirm.className = "sp-btn sp-btn-stop";
                btnConfirm.style.cssText = "font-size:.75rem;padding:6px 14px;";
                btnConfirm.textContent = "Yes, Stop All";
                btnConfirm.addEventListener("click", () => {
                    confirmBar.remove();
                    runStop(selected, modal, footer, allWorkOrders);
                });

                btnConfirmWrap.appendChild(btnDismiss);
                btnConfirmWrap.appendChild(btnConfirm);
                confirmBar.appendChild(msg);
                confirmBar.appendChild(btnConfirmWrap);

                footer.insertBefore(confirmBar, footerInfo);
            });

            const btnApprove = document.createElement("button");
            btnApprove.className = "sp-btn sp-btn-approve";
            btnApprove.textContent = "Approve Selected";
            btnApprove.disabled = true;
            btnApprove.id = "sp-approve-btn";
            btnApprove.addEventListener("click", () => {
                const selected = Object.keys(checkboxMap).filter(name => checkboxMap[name].checked);
                if (selected.length) runApproval(selected, modal, footer, allWorkOrders);
            });

            btnWrap.appendChild(btnCancel);
            btnWrap.appendChild(btnSelectAll);
            btnWrap.appendChild(btnStop);
            btnWrap.appendChild(btnApprove);
            footer.appendChild(footerInfo);
            footer.appendChild(btnWrap);
            updateFooter();

            function updateFooter() {
                const count = Object.values(checkboxMap).filter(cb => cb.checked).length;
                const info  = document.getElementById("sp-footer-info");
                if (info) info.innerHTML = "<strong>" + count + "</strong> of <strong>" + workOrders.length + "</strong> plans selected";
                const appBtn  = document.getElementById("sp-approve-btn");
                const stopBtn = document.getElementById("sp-stop-btn");
                if (appBtn)  appBtn.disabled  = count === 0;
                if (stopBtn) stopBtn.disabled = count === 0;
            }
        })
        .catch(e => {
            body.innerHTML = "<div style='color:#dc2626;padding:20px;'>Failed to load details: " + (e.message || e) + "</div>";
        });
}

// ════════════════════════════════════════════════════════════
//  WO Card builder
// ════════════════════════════════════════════════════════════

function buildWoCard(wo, checkbox) {
    const splitLines = val => (val || "").split(/\n/).map(s => s.trim()).filter(Boolean);
    const targets     = splitLines(wo.custom_targets);
    const schedDate   = wo.custom_scheduled_application_time ? wo.custom_scheduled_application_time.split(" ")[0] : "—";
    const createdDate = wo.creation
        ? new Date(wo.creation).toLocaleDateString("en-GB", { day:"numeric", month:"short", year:"numeric" })
        : "—";
    const chemicals = (wo.required_items || []).map(item => ({
        name: item.item_name || item.item_code,
        code: item.item_code,
        qty: item.required_qty,
        uom: item.stock_uom
    }));

    const card     = document.createElement("div"); card.className = "sp-wo-card";
    const cardHead = document.createElement("div"); cardHead.className = "sp-wo-card-head";
    const cbWrap   = document.createElement("label"); cbWrap.className = "sp-wo-card-cb"; cbWrap.appendChild(checkbox);
    const woInfo   = document.createElement("span"); woInfo.style.cssText = "display:flex;flex-direction:column;gap:2px;";

    const nameRow = document.createElement("span"); nameRow.style.cssText = "display:flex;align-items:center;gap:8px;";
    const nameLink = document.createElement("a");
    nameLink.href = "/app/work-order/" + wo.name; nameLink.target = "_blank";
    nameLink.style.cssText = "color:#3b82f6;font-weight:700;text-decoration:none;font-size:.88rem;";
    nameLink.textContent = wo.name;
    const typeTag = document.createElement("span"); typeTag.className = "sp-tag sp-tag-type"; typeTag.textContent = wo.custom_spray_type || "—";
    nameRow.appendChild(nameLink); nameRow.appendChild(typeTag);

    const ghLabel = document.createElement("span"); ghLabel.style.cssText = "font-size:.75rem;color:#6b7280;font-weight:500;";
    ghLabel.textContent = wo.custom_greenhouse || "";
    woInfo.appendChild(nameRow); woInfo.appendChild(ghLabel);
    cbWrap.appendChild(woInfo);

    const rightMeta = document.createElement("div"); rightMeta.style.cssText = "display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex-shrink:0;";
    const schedBadge = document.createElement("span"); schedBadge.className = "sp-wo-sched"; schedBadge.textContent = schedDate;
    const createdLabel = document.createElement("span"); createdLabel.style.cssText = "font-size:.68rem;color:#9ca3af;"; createdLabel.textContent = "Created: " + createdDate;
    rightMeta.appendChild(schedBadge); rightMeta.appendChild(createdLabel);

    cardHead.appendChild(cbWrap); cardHead.appendChild(rightMeta);
    card.appendChild(cardHead);

    const detail = (label, value) => "<div class='sp-detail-item'><span class='sp-detail-label'>" + label + "</span><span class='sp-detail-value'>" + (value || "—") + "</span></div>";
    const scopeVal = [wo.custom_scope, wo.custom_scope_details].filter(Boolean).join(" — ");
    const grid = document.createElement("div"); grid.className = "sp-wo-details";
    grid.innerHTML =
        detail("Scope",        scopeVal) +
        detail("Area",         wo.custom_area          ? wo.custom_area + " Ha"          : "—") +
        detail("Water Volume", wo.custom_water_volume   ? wo.custom_water_volume + " L"   : "—") +
        detail("Water pH",     wo.custom_water_ph       || "—") +
        detail("Hardness",     wo.custom_water_hardness ? wo.custom_water_hardness + " ppm" : "—") +
        detail("Kit",          wo.custom_kit            || "—") +
        detail("CSU / WIP",    wo.wip_warehouse         || "—");
    card.appendChild(grid);

    const targetsSection = buildTargetsPillsSection(targets, wo.custom_greenhouse || "");
    if (targetsSection) card.appendChild(targetsSection);

    if (chemicals.length) {
        const chemWrap = document.createElement("div"); chemWrap.className = "sp-wo-section";
        const chemLabel = document.createElement("span"); chemLabel.className = "sp-detail-label"; chemLabel.textContent = "Chemicals";
        chemWrap.appendChild(chemLabel);
        const tbl = document.createElement("table"); tbl.className = "sp-chem-table";
        const thead = document.createElement("thead");
        thead.innerHTML = "<tr><th>Item Name</th><th>Item Code</th><th style='text-align:right'>Qty</th><th>UoM</th></tr>";
        tbl.appendChild(thead);
        const tbody = document.createElement("tbody");
        chemicals.forEach(c => {
            const tr = document.createElement("tr");
            tr.innerHTML = "<td>" + c.name + "</td><td style='color:#6b7280'>" + c.code + "</td>" +
                "<td style='text-align:right;font-weight:600'>" + fmtQty(c.qty) + "</td><td>" + c.uom + "</td>";
            tbody.appendChild(tr);
        });
        tbl.appendChild(tbody); chemWrap.appendChild(tbl); card.appendChild(chemWrap);
    }
    return card;
}

function fmtQty(val) {
    if (val === null || val === undefined) return "—";
    const n = parseFloat(val);
    return isNaN(n) ? val : n % 1 === 0 ? n.toString() : n.toFixed(3).replace(/\.?0+$/, "");
}

// ════════════════════════════════════════════════════════════
//  Targets pills + heatmap
// ════════════════════════════════════════════════════════════

function buildTargetsPillsSection(targets, greenhouse) {
    if (!targets.length) return null;
    const wrap = document.createElement("div"); wrap.className = "sp-wo-section";
    const labelRow = document.createElement("div"); labelRow.style.cssText = "display:flex;align-items:center;gap:8px;margin-bottom:6px;";
    const lbl  = document.createElement("span"); lbl.className = "sp-detail-label"; lbl.style.marginBottom = "0"; lbl.textContent = "Targets";
    const hint = document.createElement("span"); hint.style.cssText = "font-size:.65rem;color:#9ca3af;font-style:italic;"; hint.textContent = "click to view heatmap";
    labelRow.appendChild(lbl); labelRow.appendChild(hint); wrap.appendChild(labelRow);
    const pills = document.createElement("div"); pills.className = "sp-pills";
    targets.forEach(t => {
        const p = document.createElement("span"); p.className = "sp-pill"; p.textContent = t;
        pills.appendChild(p);
        attachTargetHeatmap(p, greenhouse, t);
    });
    wrap.appendChild(pills);
    return wrap;
}

function attachTargetHeatmap(pill, greenhouse, targetName) {
    pill.style.cursor = "pointer";
    pill.addEventListener("mouseenter", () => { pill.style.borderColor="#3b82f6"; pill.style.color="#1d4ed8"; pill.style.background="#eff6ff"; });
    pill.addEventListener("mouseleave", () => { pill.style.borderColor=""; pill.style.color=""; pill.style.background=""; });
    pill.addEventListener("click", e => { e.stopPropagation(); openTargetHeatmap(greenhouse, targetName); });
}

// ════════════════════════════════════════════════════════════
//  STEP 3a — Run approval (Material Transfer for Manufacture)
// ════════════════════════════════════════════════════════════

function runApproval(woNames, modal, footer, allWorkOrders) {
    _loadQrLib().catch(() => {});
    buildProgressUI(footer, "Approving " + woNames.length + " spray plan" + (woNames.length !== 1 ? "s" : "") + "...", false);

    const title       = footer.querySelector(".sp-run-title");
    const progressBar = footer.querySelector(".sp-progress-bar");
    const log         = footer.querySelector(".sp-status-log");
    const closeBtn    = footer.querySelector(".sp-run-close");
    const qrSection   = footer.querySelector(".sp-qr-section");

    let done = 0, errors = 0, approvedPairs = [];

    function advance() { done++; progressBar.style.width = Math.round((done / woNames.length) * 100) + "%"; }
    function addLog(html, cls) { const line = document.createElement("div"); if (cls) line.className = cls; line.innerHTML = html; log.appendChild(line); log.scrollTop = log.scrollHeight; }

    function processNext(index) {
        if (index >= woNames.length) {
            title.textContent = "Done — " + (done - errors) + " approved, " + errors + " failed.";
            title.style.color = errors === 0 ? "#059669" : errors === done ? "#dc2626" : "#d97706";

            if (approvedPairs.length > 0) {
                addLog("Generating QR labels...", "sp-log-warn");
                _loadQrLib().then(() => generateAndAttachQrCodes(approvedPairs))
                    .then(qrResults => {
                        addLog(qrResults.total + " QR label" + (qrResults.total !== 1 ? "s" : "") + " generated and attached.", "sp-log-ok");
                        if (qrResults.attachErrors > 0) addLog(qrResults.attachErrors + " label(s) could not be attached.", "sp-log-warn");
                        renderQrPrintSection(qrSection, qrResults.labels);
                    })
                    .catch(qrErr => addLog("QR generation failed: " + (qrErr.message || qrErr), "sp-log-warn"))
                    .finally(() => { closeBtn.style.display = "block"; });
            } else {
                closeBtn.style.display = "block";
            }
            return;
        }

        const woName = woNames[index];
        const wo = allWorkOrders.find(w => w.name === woName);

        function proceed(woDoc) {
            if (woDoc.status !== "Not Started") {
                addLog("&#9888; <strong>" + woName + "</strong> — skipped (status: " + woDoc.status + ")", "sp-log-warn");
                errors++; advance(); processNext(index + 1); return;
            }
            frappe.call({
                method: "erpnext.manufacturing.doctype.work_order.work_order.make_stock_entry",
                args:   { work_order_id: woName, purpose: "Material Transfer for Manufacture" }
            }).then(seResp => {
                const seDraft = seResp.message;
                if (!seDraft) throw new Error("Empty stock entry response");
                return frappe.call({ method: "frappe.client.insert", args: { doc: seDraft } });
            }).then(insertResp => {
                const savedSe = insertResp.message;
                return frappe.call({
                    method: "frappe.desk.form.run_method.run",
                    args: { dt: "Stock Entry", dn: savedSe.name, method: "get_stock_and_rate" }
                }).then(r => {
                    console.log("[Spray Approval] Valuation rates fetched for", savedSe.name, r.message || r);
                    return savedSe;
                }).catch(e => {
                    console.warn("[Spray Approval] get_stock_and_rate failed for", savedSe.name, "- proceeding:", e);
                    return savedSe;
                });
            }).then(savedSe => {
                approvedPairs.push({ wo: woDoc, seName: savedSe.name });
                addLog("&#10003; <strong>" + woName + "</strong> — Transfer <a href='/app/stock-entry/" + savedSe.name + "' target='_blank' style='color:#059669'>" + savedSe.name + "</a> raised to <strong>" + woDoc.wip_warehouse + "</strong>", "sp-log-ok");
                advance(); processNext(index + 1);
            }).catch(err => {
                addLog("&#10007; <strong>" + woName + "</strong> — " + (err.message || err.exception || JSON.stringify(err)), "sp-log-err");
                errors++; advance(); processNext(index + 1);
            });
        }

        if (wo) { proceed(wo); } else {
            frappe.db.get_doc("Work Order", woName).then(proceed).catch(err => {
                addLog("&#10007; <strong>" + woName + "</strong> — " + (err.message || err), "sp-log-err");
                errors++; advance(); processNext(index + 1);
            });
        }
    }

    processNext(0);
}

// ════════════════════════════════════════════════════════════
//  STEP 3b — Run Stop (bulk cancel via stop_unstop)
// ════════════════════════════════════════════════════════════

function runStop(woNames, modal, footer, allWorkOrders) {
    buildProgressUI(footer, "Stopping " + woNames.length + " work order" + (woNames.length !== 1 ? "s" : "") + "...", true);

    const title       = footer.querySelector(".sp-run-title");
    const progressBar = footer.querySelector(".sp-progress-bar");
    const log         = footer.querySelector(".sp-status-log");
    const closeBtn    = footer.querySelector(".sp-run-close");

    let done = 0, errors = 0;

    function advance() { done++; progressBar.style.width = Math.round((done / woNames.length) * 100) + "%"; }
    function addLog(html, cls) { const line = document.createElement("div"); if (cls) line.className = cls; line.innerHTML = html; log.appendChild(line); log.scrollTop = log.scrollHeight; }

    function processNext(index) {
        if (index >= woNames.length) {
            title.textContent = "Done — " + (done - errors) + " stopped, " + errors + " failed.";
            title.style.color = errors === 0 ? "#dc2626" : errors === done ? "#dc2626" : "#d97706";
            closeBtn.style.display = "block";
            return;
        }

        const woName = woNames[index];

        frappe.call({
            method: "erpnext.manufacturing.doctype.work_order.work_order.stop_unstop",
            args:   { work_order: woName, status: "Stopped" }
        }).then(() => {
            addLog("&#9632; <strong>" + woName + "</strong> — stopped successfully.", "sp-log-stop");
            advance(); processNext(index + 1);
        }).catch(err => {
            addLog("&#10007; <strong>" + woName + "</strong> — " + (err.message || err.exception || JSON.stringify(err)), "sp-log-err");
            errors++; advance(); processNext(index + 1);
        });
    }

    processNext(0);
}

// ── Shared progress UI builder ────────────────────────────────
function buildProgressUI(footer, titleText, isStop) {
    footer.innerHTML = "";
    footer.style.flexDirection = "column";
    footer.style.alignItems    = "stretch";

    const title = document.createElement("div");
    title.className = "sp-run-title";
    title.style.cssText = "font-weight:600;margin-bottom:8px;color:#111827;";
    title.textContent = titleText;
    footer.appendChild(title);

    const progressWrap = document.createElement("div"); progressWrap.className = "sp-progress-wrap";
    const progressBar  = document.createElement("div");
    progressBar.className = isStop ? "sp-progress-bar-stop" : "sp-progress-bar";
    progressBar.style.width = "0%";
    progressWrap.appendChild(progressBar);
    footer.appendChild(progressWrap);

    const log = document.createElement("div"); log.className = "sp-status-log"; footer.appendChild(log);

    const qrSection = document.createElement("div"); qrSection.className = "sp-qr-section"; qrSection.style.display = "none"; footer.appendChild(qrSection);

    const closeBtn = document.createElement("button");
    closeBtn.className = "sp-run-close sp-btn sp-btn-cancel";
    closeBtn.textContent = "Close";
    closeBtn.style.cssText = "margin-top:12px;align-self:flex-end;display:none;";
    closeBtn.addEventListener("click", () => {
        footer.closest(".sp-overlay").remove();
        if (typeof cur_list !== "undefined" && cur_list) cur_list.refresh();
    });
    footer.appendChild(closeBtn);
}

// ════════════════════════════════════════════════════════════
//  PNG attachment
// ════════════════════════════════════════════════════════════

const MAX_ATTACH_RETRIES = 3;
const ATTACH_RETRY_DELAY = 300;

function attachPngToDocument(pngBase64, fileName, doctype, docname) {
    let attempt = 0;
    function tryUpload() {
        attempt++;
        const binaryString = atob(pngBase64);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) { bytes[i] = binaryString.charCodeAt(i); }
        const blob = new Blob([bytes], { type: "image/png" });
        const file = new File([blob], fileName, { type: "image/png" });
        const formData = new FormData();
        formData.append("file",       file, fileName);
        formData.append("doctype",    doctype);
        formData.append("docname",    docname);
        formData.append("fieldname",  "attach");
        formData.append("is_private", "1");
        return fetch("/api/method/upload_file", {
            method: "POST", headers: { "X-Frappe-CSRF-Token": frappe.csrf_token }, body: formData
        }).then(response => {
            if (!response.ok) return response.text().then(t => { throw new Error("HTTP " + response.status + ": " + t.slice(0, 300)); });
            return response.json();
        }).then(result => {
            if (result.exc) throw new Error(result.exc);
            return result;
        }).catch(err => {
            console.warn("[QR] Attempt " + attempt + "/" + MAX_ATTACH_RETRIES + " failed:", err);
            if (attempt < MAX_ATTACH_RETRIES) return new Promise(res => setTimeout(res, ATTACH_RETRY_DELAY * attempt)).then(tryUpload);
            throw err;
        });
    }
    return tryUpload();
}

// ════════════════════════════════════════════════════════════
//  QR Code generation + attachment
// ════════════════════════════════════════════════════════════

function generateAndAttachQrCodes(approvedPairs) {
    const labels = [];
    let attachErrors = 0;

    function processChemical(pairs, pi, ci) {
        if (pi >= pairs.length) return Promise.resolve({ total: labels.length, labels, attachErrors });
        const wo = pairs[pi].wo, seName = pairs[pi].seName;
        const chemicals = (wo.required_items || []).map(item => ({
            name: item.item_name || item.item_code,
            code: item.item_code,
            qty: item.required_qty,
            uom: item.stock_uom,
            srcWh: item.s_warehouse || ""
        }));
        if (ci >= chemicals.length) return processChemical(pairs, pi + 1, 0);
        const chem = chemicals[ci];
        const payload = ["CHEM: " + chem.name, "QTY: " + fmtQty(chem.qty) + " " + chem.uom, "WO: " + wo.name, "SE: " + seName, "GH: " + (wo.custom_greenhouse || ""), "DATE: " + new Date().toLocaleDateString("en-GB")].join("\n");
        return renderQrToBase64(payload, 400).then(pngBase64 => {
            const safeCode = chem.code.replace(/[^a-zA-Z0-9]/g, "_");
            const fileName = "QR_" + seName + "_" + safeCode + ".png";
            return attachPngToDocument(pngBase64, fileName, "Stock Entry", seName)
                .catch(err => { attachErrors++; console.warn("[QR] Attach failed:", err); })
                .then(() => {
                    labels.push({ wo: wo.name, se: seName, greenhouse: wo.custom_greenhouse || "", chemical: chem.name, qty: chem.qty, uom: chem.uom, srcWh: chem.srcWh, pngBase64 });
                    return processChemical(pairs, pi, ci + 1);
                });
        });
    }
    return processChemical(approvedPairs, 0, 0);
}

function renderQrToBase64(text, size) {
    size = size || 400;
    return new Promise((resolve, reject) => {
        const container = document.createElement("div");
        container.style.cssText = "position:absolute;left:-9999px;top:-9999px;width:0;height:0;overflow:hidden;";
        document.body.appendChild(container);
        try {
            new QRCode(container, { text, width: size, height: size, colorDark: "#000000", colorLight: "#ffffff", correctLevel: QRCode.CorrectLevel.L });
        } catch(err) { safeRemove(container); reject(err); return; }
        let attempts = 20;
        function poll() {
            const canvas = container.querySelector("canvas");
            if (canvas) { resolve(canvas.toDataURL("image/png").split(",")[1]); safeRemove(container); return; }
            const img = container.querySelector("img[src^='data:']");
            if (img)   { resolve(img.src.split(",")[1]); safeRemove(container); return; }
            if (--attempts <= 0) { safeRemove(container); reject(new Error("QR render timed out")); return; }
            setTimeout(poll, 50);
        }
        setTimeout(poll, 50);
    });
}

function safeRemove(el) { try { document.body.removeChild(el); } catch(_) {} }

// ════════════════════════════════════════════════════════════
//  QR Print Sheet
// ════════════════════════════════════════════════════════════

function renderQrPrintSection(container, labels) {
    if (!labels.length) return;
    container.style.cssText = "display:block;margin-top:16px;border-top:2px solid #e5e7eb;padding-top:14px;";
    const header = document.createElement("div"); header.style.cssText = "display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;";
    const headerTitle = document.createElement("span"); headerTitle.style.cssText = "font-size:.85rem;font-weight:700;color:#111827;"; headerTitle.textContent = "Chemical QR Labels (" + labels.length + ")";
    const printBtn = document.createElement("button"); printBtn.className = "sp-btn sp-btn-approve"; printBtn.style.cssText = "padding:7px 16px;font-size:.78rem;"; printBtn.textContent = "Print / Download Labels";
    printBtn.addEventListener("click", () => openQrPrintWindow(labels));
    header.appendChild(headerTitle); header.appendChild(printBtn); container.appendChild(header);
    const strip = document.createElement("div"); strip.style.cssText = "display:flex;flex-wrap:wrap;gap:10px;max-height:180px;overflow-y:auto;padding:10px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;";
    labels.forEach(lbl => {
        const chip = document.createElement("div"); chip.style.cssText = "display:flex;align-items:center;gap:8px;padding:6px 10px;background:#fff;border:1px solid #e5e7eb;border-radius:8px;font-size:.72rem;color:#374151;";
        const img = document.createElement("img"); img.src = "data:image/png;base64," + lbl.pngBase64; img.style.cssText = "width:48px;height:48px;border-radius:4px;image-rendering:pixelated;";
        const info = document.createElement("div");
        const cn = document.createElement("div"); cn.style.cssText = "font-weight:700;color:#111827;"; cn.textContent = lbl.chemical;
        const cm = document.createElement("div"); cm.style.cssText = "color:#6b7280;"; cm.textContent = lbl.wo + " · " + fmtQty(lbl.qty) + " " + lbl.uom;
        info.appendChild(cn); info.appendChild(cm); chip.appendChild(img); chip.appendChild(info); strip.appendChild(chip);
    });
    container.appendChild(strip);
}

function openQrPrintWindow(labels) {
    const win = window.open("", "_blank", "width=960,height=720");
    if (!win) { frappe.msgprint("Pop-ups blocked. Please allow pop-ups for this site."); return; }
    const labelHtml = labels.map(lbl => {
        return "<div class='label'><div class='label-header'><div class='label-title'>" + escHtml(lbl.chemical) + "</div><div class='label-sub'>" + escHtml(lbl.greenhouse) + "</div></div>" +
            "<div class='label-body'><img src='data:image/png;base64," + lbl.pngBase64 + "' class='qr-img'>" +
            "<div class='label-meta'>" +
            "<div class='meta-row'><span class='meta-key'>Work Order</span><span class='meta-val'>"     + escHtml(lbl.wo)     + "</span></div>" +
