function deriveFarm(greenhouse) {
    if (!greenhouse) return null;
    const match = greenhouse.match(/^(.+?)\s+GH\b/i);
    return match ? match[1].trim() : greenhouse.split(" ")[0];
}

function syncGhCheckbox(ghCheck, ghCheckboxes) {
    const checked = ghCheckboxes.filter(c => c.checked).length;
    ghCheck.checked       = checked === ghCheckboxes.length;
    ghCheck.indeterminate = checked > 0 && checked < ghCheckboxes.length;
}

function buildOverlay() { const el = document.createElement("div"); el.className = "sp-overlay"; return el; }
function buildModal()   { const el = document.createElement("div"); el.className = "sp-modal";   return el; }

function buildHeader(title, onClose, onBack) {
    const el = document.createElement("div"); el.className = "sp-header";
    if (onBack) {
        const backBtn = document.createElement("button"); backBtn.className = "sp-back"; backBtn.innerHTML = "&#8592; Back";
        backBtn.addEventListener("click", onBack);
        el.appendChild(backBtn);
    }
    const h3 = document.createElement("h3");  h3.textContent = title;
    const btn = document.createElement("button"); btn.className = "sp-close"; btn.innerHTML = "&times;";
    btn.addEventListener("click", onClose);
    el.appendChild(h3); el.appendChild(btn); return el;
}

